            exx		; Hyp.cls 438
            push af		; Hyp.cls 439
            push bc		; Hyp.cls 440
            push de		; Hyp.cls 441
            push hl		; Hyp.cls 442
            push ix		; Hyp.cls 443
            push iy		; Hyp.cls 444
